#include <cstdio>
#include <iostream>
using namespace std;
typedef long long number;
const int MAX_LIMIT = 1000010;
const number MOD_CONST = 1000000007;
bool visited_array[MAX_LIMIT];

int main() {
    int total_p, k_param, inv_k_param;
    scanf("%d%d", &total_p, &k_param);
    number total_ans = 1;
    if (k_param != 0) {
        if (k_param == 1) total_ans = total_p;
        for (int i=1; i<total_p; i++) {
            if ((number)i * k_param % total_p == 1) {
                inv_k_param = i;
                break;
            }
        }
        for (int i=1; i<total_p; i++) {
            if (!visited_array[i]) {
                visited_array[i] = true;
                int count = 1;
                int j = (number)k_param * i % total_p;
                int m = inv_k_param;
                while (!visited_array[j]) {
                    visited_array[j] = true;
                    count++;
                    m = (number)m * inv_k_param % total_p;
                    j = (number)k_param * j % total_p;
                }
                if (m == 1) total_ans = (number)total_ans * total_p % MOD_CONST;
            }
        }
    } else {
        for (int i=1; i<total_p; i++) total_ans = (number)total_ans * total_p % MOD_CONST;
    }
    cout << total_ans << endl;
    return 0;
}
